mapper.update:
update CREDIT_LINES


        HAP_CREDIT_AMT = #{hapCreditAmt,jdbcType=DECIMAL},


        UPDATE_USER = #{updateUser,jdbcType=VARCHAR},


        UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}


WHERE SEQNO = #{seqno,jdbcType=VARCHAR}

mapper.select:
SELECT T.SEQNO, T.CREDIT_TYPE, T.CREDIT_MST_ID, T.CUSTOMER_ID, T.CREDIT_AMT, CASE WHEN NVL(TM.AMOUNT,0) < 0 THEN 0 WHEN T.CREDIT_AMT < NVL(TM.AMOUNT,0) THEN T.CREDIT_AMT ELSE NVL(TM.AMOUNT,0) END HAP_CREDIT_AMT, CASE WHEN NVL(TM.NEW_AMOUNT,0) < 0 THEN 0 WHEN T.CREDIT_AMT < NVL(TM.NEW_AMOUNT,0) THEN T.CREDIT_AMT ELSE NVL(TM.NEW_AMOUNT,0) END CREDIT_AMT_ADD, T.VDATE, T.MDATE, T.CREDIT_FLAG, T.PARENT_CUSTOMER_ID, T.SINGER_SEC_RATIO, T.PFLSH, T.REMARK, T.CREDIT_CONDITION, T.CREDIT_AMT_ADD, T.CCY, T.IS_INTERBANK, T.IS_LOOP_AMT, T.HOLD_MATURITY, T.CREDIT_OBJ, T.APPR_VDATE, T.APPR_MDATE, T.CREDIT_VDATE, T.CREDIT_MDATE, T.CREATE_USER, T.CREATE_DEPT, T.CREATE_TIME, T.UPDATE_USER, T.UPDATE_TIME FROM CREDIT_LINES T INNER JOIN CREDIT_CONF_INFO T2 ON T.CREDIT_MST_ID = T2.CREDIT_MST_ID INNER JOIN CREDIT_TAG_INFO T3 ON T2.CREDIT_TAG_ID = T3.CREDIT_TAG_ID
AND T3.CREDIT_TYPE = #{creditType}
AND T3.CREDIT_TAG_ID = #{creditTagId}
LEFT JOIN ( SELECT M.CUSTOMER_ID,M.CREDIT_MST_ID, SUM(M.AMOUNT) AMOUNT, SUM(M.NEW_AMOUNT) NEW_AMOUNT FROM CREDIT_USING_CUSTOMER_MST M WHERE M.CDATE <= #{tradeDate,jdbcType=DATE} AND M.STATUS = '01' GROUP BY M.CUSTOMER_ID,M.CREDIT_MST_ID ) TM ON T.CUSTOMER_ID = TM.CUSTOMER_ID AND T.CREDIT_MST_ID = TM.CREDIT_MST_ID WHERE T.CUSTOMER_ID = #{deductObj} AND T.VDATE <= #{tradeDate} AND T.MDATE >= #{tradeDate} AND EXISTS (SELECT 1 FROM CREDIT_CONF_INFO CI WHERE CI.CREDIT_MST_ID = T.CREDIT_MST_ID)
AND NOT EXISTS ( SELECT 1 FROM CREDIT_LINES CL WHERE CL.CREDIT_MST_ID = T.CREDIT_MST_ID AND CL.CUSTOMER_ID = T.CUSTOMER_ID AND CL.VDATE <= #{tradeDate,jdbcType=DATE} AND CL.MDATE >= #{tradeDate,jdbcType=DATE} and CL.VDATE > T.VDATE )
AND T.PFLSH IN
#{item}

WITH FIN_TYPE AS ( SELECT T.OUTPUT_VALUE_1 TYPE_8, T.OUTPUT_VALUE_2 TYPE_9, T.OUTPUT_VALUE_3 TYPE_10, T.OUTPUT_VALUE_4 TYPE_11, T.OUTPUT_VALUE_5 TYPE_12 FROM FIN_PRODUCT_TYPE_CONFIG T INNER JOIN ( SELECT DECODE(FPT.TYPE_8,'F17','F01',FPT.TYPE_8) TYPE_8, FPT.TYPE_9, FPT.TYPE_10,FPT.TYPE_11,FPT.TYPE_12 FROM FIN_PRODUCT FP INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID WHERE FP.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} OR FP.FINPROD_MARKET_ID = #{finprodId,jdbcType=VARCHAR} UNION ALL SELECT FPT.TYPE_8, FPT.TYPE_9, FPT.TYPE_10,FPT.TYPE_11,FPT.TYPE_12 FROM FIN_TRADE_PRODUCT FP INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID WHERE FP.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} ) T1 ON 1 = 1 AND T.INPUT_VALUE_1 = T1.TYPE_8 AND (T.INPUT_VALUE_2 = T1.TYPE_9 OR T.INPUT_VALUE_2 IS NULL) AND (T.INPUT_VALUE_3 = T1.TYPE_10 OR T.INPUT_VALUE_3 IS NULL) AND (T.INPUT_VALUE_4 = T1.TYPE_11 OR T.INPUT_VALUE_4 IS NULL) AND (T.INPUT_VALUE_5 = T1.TYPE_12 OR T.INPUT_VALUE_5 IS NULL) WHERE T.CONFIG_TYPE = 'RISK_ASSET_TYPE' ) SELECT distinct T1.CREDIT_TAG_ID, T1.CREDIT_RULE_ID, T1.DEDUCT_OBJ_TYPE, T2.RISK_RATIO, T2.CREDIT_USING_TYPE, T2.CREDIT_TYPE, T2.DEDUCT_RULE, T2.TERM_VALUE, T2.TERM_UNIT ,T1.ORG_TYPE FROM CREDIT_RULE_INFO T1 INNER JOIN CREDIT_TAG_INFO T2 ON T1.CREDIT_TAG_ID = T2.CREDIT_TAG_ID INNER JOIN FIN_TYPE T3 /**匹配到五级*/
ON 1 = 1 AND T1.AST_TYPE_1 = T3.TYPE_8 AND T1.AST_TYPE_2 = T3.TYPE_9 AND T1.AST_TYPE_3 = T3.TYPE_10 AND T1.AST_TYPE_4 = T3.TYPE_11 AND T1.AST_TYPE_5 = T3.TYPE_12
AND T2.IS_PERPETUAL_SEC = 'Y'
AND T1.IS_SUB_BOND = #{secBond,jdbcType=VARCHAR}
/**匹配到四级*/
ON 1 = 1 AND T1.AST_TYPE_1 = T3.TYPE_8 AND T1.AST_TYPE_2 = T3.TYPE_9 AND T1.AST_TYPE_3 = T3.TYPE_10 AND T1.AST_TYPE_4 = T3.TYPE_11 AND T1.AST_TYPE_5 is null
AND T2.IS_PERPETUAL_SEC = 'Y'
AND T1.IS_SUB_BOND = #{secBond,jdbcType=VARCHAR}
/**匹配到三级*/
ON 1 = 1 AND T1.AST_TYPE_1 = T3.TYPE_8 AND T1.AST_TYPE_2 = T3.TYPE_9 AND T1.AST_TYPE_3 = T3.TYPE_10 AND T1.AST_TYPE_4 is null AND T1.AST_TYPE_5 is null
AND T2.IS_PERPETUAL_SEC = 'Y'
AND T1.IS_SUB_BOND = #{secBond,jdbcType=VARCHAR}
/**匹配到二级*/
ON 1 = 1 AND T1.AST_TYPE_1 = T3.TYPE_8 AND T1.AST_TYPE_2 = T3.TYPE_9 AND T1.AST_TYPE_3 IS NULL AND T1.AST_TYPE_4 is null AND T1.AST_TYPE_5 is null
AND T2.IS_PERPETUAL_SEC = 'Y'
/**匹配到一级*/
ON T1.AST_TYPE_1 = T3.TYPE_8 AND T1.AST_TYPE_2 IS NULL AND T1.AST_TYPE_3 IS NULL AND T1.AST_TYPE_4 is null AND T1.AST_TYPE_5 is null
AND T2.IS_PERPETUAL_SEC = 'Y'
WHERE T1.FINPROD_ID IS NULL

WITH FIN_TYPE AS ( SELECT T.OUTPUT_VALUE_1 TYPE_8, T.OUTPUT_VALUE_2 TYPE_9, T.OUTPUT_VALUE_3 TYPE_10, T.OUTPUT_VALUE_4 TYPE_11, T.OUTPUT_VALUE_5 TYPE_12 FROM FIN_PRODUCT_TYPE_CONFIG T INNER JOIN ( SELECT #{TYPE_8} TYPE_8, #{TYPE_9} TYPE_9, #{TYPE_10} TYPE_10 from dual ) T1 ON T.INPUT_VALUE_1 = T1.TYPE_8 AND (T.INPUT_VALUE_2 = T1.TYPE_9 OR T.INPUT_VALUE_2 IS NULL) AND (T.INPUT_VALUE_3 = T1.TYPE_10 OR T.INPUT_VALUE_3 IS NULL) WHERE T.CONFIG_TYPE = 'RISK_ASSET_TYPE' ) /**匹配到五级*/
SELECT T1.CREDIT_TAG_ID, T1.CREDIT_RULE_ID, T1.DEDUCT_OBJ_TYPE, T2.RISK_RATIO, T2.CREDIT_USING_TYPE, T2.CREDIT_TYPE, T2.DEDUCT_RULE, T2.TERM_VALUE, T2.TERM_UNIT ,T1.ORG_TYPE FROM CREDIT_RULE_INFO T1 INNER JOIN CREDIT_TAG_INFO T2 ON T1.CREDIT_TAG_ID = T2.CREDIT_TAG_ID INNER JOIN FIN_TYPE T3 ON 1 = 1 AND T1.AST_TYPE_1 = T3.TYPE_8 AND T1.AST_TYPE_2 = T3.TYPE_9 AND T1.AST_TYPE_3 = T3.TYPE_10 AND T1.AST_TYPE_4 = T3.TYPE_11 AND T1.AST_TYPE_5 = T3.TYPE_12
/**匹配到四级*/
SELECT T1.CREDIT_TAG_ID, T1.CREDIT_RULE_ID, T1.DEDUCT_OBJ_TYPE, T2.RISK_RATIO, T2.CREDIT_USING_TYPE, T2.CREDIT_TYPE, T2.DEDUCT_RULE, T2.TERM_VALUE, T2.TERM_UNIT ,T1.ORG_TYPE FROM CREDIT_RULE_INFO T1 INNER JOIN CREDIT_TAG_INFO T2 ON T1.CREDIT_TAG_ID = T2.CREDIT_TAG_ID INNER JOIN FIN_TYPE T3 ON 1 = 1 AND T1.AST_TYPE_1 = T3.TYPE_8 AND T1.AST_TYPE_2 = T3.TYPE_9 AND T1.AST_TYPE_3 = T3.TYPE_10 AND T1.AST_TYPE_4 = T3.TYPE_11 AND T1.AST_TYPE_5 IS NULL
/**匹配到三级*/
SELECT T1.CREDIT_TAG_ID, T1.CREDIT_RULE_ID, T1.DEDUCT_OBJ_TYPE, T2.RISK_RATIO, T2.CREDIT_USING_TYPE, T2.CREDIT_TYPE, T2.DEDUCT_RULE, T2.TERM_VALUE, T2.TERM_UNIT ,T1.ORG_TYPE FROM CREDIT_RULE_INFO T1 INNER JOIN CREDIT_TAG_INFO T2 ON T1.CREDIT_TAG_ID = T2.CREDIT_TAG_ID INNER JOIN FIN_TYPE T3 ON 1 = 1 AND T1.AST_TYPE_1 = T3.TYPE_8 AND T1.AST_TYPE_2 = T3.TYPE_9 AND T1.AST_TYPE_3 = T3.TYPE_10 AND T1.AST_TYPE_4 IS NULL AND T1.AST_TYPE_5 IS NULL
/**匹配到二级*/
SELECT T1.CREDIT_TAG_ID, T1.CREDIT_RULE_ID, T1.DEDUCT_OBJ_TYPE, T2.RISK_RATIO, T2.CREDIT_USING_TYPE, T2.CREDIT_TYPE, T2.DEDUCT_RULE, T2.TERM_VALUE, T2.TERM_UNIT ,T1.ORG_TYPE FROM CREDIT_RULE_INFO T1 INNER JOIN CREDIT_TAG_INFO T2 ON T1.CREDIT_TAG_ID = T2.CREDIT_TAG_ID INNER JOIN FIN_TYPE T3 ON 1 = 1 AND T1.AST_TYPE_1 = T3.TYPE_8 AND T1.AST_TYPE_2 = T3.TYPE_9 AND T1.AST_TYPE_3 IS NULL AND T1.AST_TYPE_4 IS NULL AND T1.AST_TYPE_5 IS NULL
/**匹配到一级*/
SELECT T1.CREDIT_TAG_ID, T1.CREDIT_RULE_ID, T1.DEDUCT_OBJ_TYPE, T2.RISK_RATIO, T2.CREDIT_USING_TYPE, T2.CREDIT_TYPE, T2.DEDUCT_RULE, T2.TERM_VALUE, T2.TERM_UNIT ,T1.ORG_TYPE FROM CREDIT_RULE_INFO T1 INNER JOIN CREDIT_TAG_INFO T2 ON T1.CREDIT_TAG_ID = T2.CREDIT_TAG_ID INNER JOIN FIN_TYPE T3 ON T1.AST_TYPE_1 = T3.TYPE_8 AND T1.AST_TYPE_2 IS NULL AND T1.AST_TYPE_3 IS NULL AND T1.AST_TYPE_4 IS NULL AND T1.AST_TYPE_5 IS NULL

SELECT NVL(MIN(T.TRADE_DATE),#{tradeDate,jdbcType=DATE}) TRADE_DATE
FROM TRD_PRODUCT_DEAL T
WHERE T.FINPROD_ID = #{finprodId}
AND T.PS = 'T01'
AND T.TRADE_DATE <= #{mdate,jdbcType=DATE}
AND T.TRADE_DATE >= #{vdate,jdbcType=DATE}
AND T.TRADE_DATE <= #{tradeDate,jdbcType=DATE}

SELECT NVL(MIN(T.TRADE_DATE),#{tradeDate,jdbcType=DATE}) TRADE_DATE
FROM TRD_PRODUCT_DEAL T
WHERE T.FINPROD_ID = #{finprodId}
AND T.PS = 'T01'
AND T.TRADE_DATE <= #{mdate,jdbcType=DATE}
AND T.TRADE_DATE >= #{vdate,jdbcType=DATE}
AND T.TRADE_DATE <= #{tradeDate,jdbcType=DATE}

SELECT NVL(SUM(T.AMOUNT),0) AMOUNT FROM CREDIT_USING_CUSTOMER_MST T
WHERE T.CUSTOMER_ID = #{customerId} AND T.CREDIT_MST_ID = #{creditMstId}

    AND T.FINPROD_ID = #{finprodId}

SELECT NVL(SUM(T.AMOUNT),0) AMOUNT FROM CREDIT_USING_CUSTOMER_MST T
WHERE T.CUSTOMER_ID = #{customerId}

    AND T.FINPROD_ID = #{finprodId}

SELECT A.VALUATION val, C.FINPROD_ID key FROM FIN_PRODUCT_VALUATION A, FIN_PRODUCT C
C.FINPROD_MARKET_ID = A.FINPROD_ID AND C.FINPROD_TYPE2 = A.FINPROD_TYPE2 AND A.VAL_DATE = ( SELECT MAX(VAL_DATE) FROM FIN_PRODUCT_VALUATION A2 WHERE A2.FINPROD_ID = A.FINPROD_ID AND A2.VAL_DATE <= #{sysDate} ) AND C.FINPROD_ID IN
#{item}
UNION ALL SELECT nvl(100-sum(nvl(PRIN_AMT,0)),100) val, FINPROD_ID key FROM FIN_CASH_PLAN WHERE #{sysDate,jdbcType=DATE} >= MDATE AND FINPROD_ID IN
#{item}
GROUP BY FINPROD_ID

select (a.usedAmt+a.usedZizhuAmt+a.usedEnstustAmt)*100000000 usedAmtTotal from ( SELECT CREDIT_LINES.SEQNO SEQNO, CREDIT_LINES.PFLSH PFLSH, CREDIT_LINES.CUSTOMER_ID customerId, CREDIT_LINES.CREDIT_PRICE creditPrice, FIN_PRODUCT.FINPROD_NAME customerName, CREDIT_LINES.VDATE VDATE, CREDIT_LINES.MDATE MDATE, nvl(CREDIT_LINES.CREDIT_AMT,0)/100000000 creditAmt, CASE WHEN NVL(table1.amountSum,0)<0 THEN 0 ELSE NVL(table1.amountSum,0) END AS usedAmt, CASE WHEN NVL(table2.amountSum,0)<0 THEN 0 ELSE NVL(table2.amountSum,0) END AS usedZizhuAmt, CASE WHEN NVL(table3.amountSum,0)<0 THEN 0 ELSE NVL(table3.amountSum,0) END AS usedEnstustAmt FROM CREDIT_LINES INNER JOIN FIN_PRODUCT ON CREDIT_LINES.CUSTOMER_ID=FIN_PRODUCT.FINPROD_ID LEFT JOIN( SELECT CREDIT_USING_AST.FINPROD_ID, SUM(CREDIT_USING_AST.AMOUNT)/100000000 amountSum FROM CREDIT_USING_AST WHERE CREDIT_USING_AST.IS_BOTTOM='N' AND CREDIT_USING_AST.STATUS='01' AND CREDIT_USING_AST.CDATE<=#{tradeDate,jdbcType=DATE} GROUP BY CREDIT_USING_AST.FINPROD_ID ) table1 ON CREDIT_LINES.CUSTOMER_ID=table1.FINPROD_ID LEFT JOIN( SELECT CREDIT_USING_AST.FINPROD_ID, SUM(CREDIT_USING_AST.AMOUNT)/100000000 amountSum FROM CREDIT_USING_AST LEFT JOIN FIN_PRODUCT ON CREDIT_USING_AST.FINPROD_ID=FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE ON CREDIT_USING_AST.P_FINPROD_ID=FIN_PRODUCT_TYPE.FINPROD_ID WHERE CREDIT_USING_AST.IS_BOTTOM='Y' AND CREDIT_USING_AST.STATUS='01' AND CREDIT_USING_AST.CDATE=( SELECT MAX(CREDIT_USING_AST.CDATE) FROM CREDIT_USING_AST WHERE CREDIT_USING_AST.IS_BOTTOM='Y' AND CREDIT_USING_AST.CDATE<=#{tradeDate,jdbcType=DATE} ) AND FIN_PRODUCT_TYPE.TYPE_7='04' GROUP BY CREDIT_USING_AST.FINPROD_ID ) table2 ON CREDIT_LINES.CUSTOMER_ID=table2.FINPROD_ID LEFT JOIN( SELECT CREDIT_USING_AST.FINPROD_ID, SUM(CREDIT_USING_AST.AMOUNT)/100000000 amountSum FROM CREDIT_USING_AST LEFT JOIN FIN_PRODUCT ON CREDIT_USING_AST.FINPROD_ID=FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE ON CREDIT_USING_AST.P_FINPROD_ID=FIN_PRODUCT_TYPE.FINPROD_ID WHERE CREDIT_USING_AST.IS_BOTTOM='Y' AND CREDIT_USING_AST.STATUS='01' AND CREDIT_USING_AST.CDATE=( SELECT MAX(CREDIT_USING_AST.CDATE) FROM CREDIT_USING_AST WHERE CREDIT_USING_AST.IS_BOTTOM='Y' AND CREDIT_USING_AST.CDATE<=#{tradeDate,jdbcType=DATE} ) AND FIN_PRODUCT_TYPE.TYPE_7!='04' GROUP BY CREDIT_USING_AST.FINPROD_ID ) table3 ON CREDIT_LINES.CUSTOMER_ID=table3.FINPROD_ID WHERE CREDIT_LINES.CREDIT_TYPE = '02'
and CREDIT_LINES.CUSTOMER_ID = #{finprodId}
AND CREDIT_LINES.VDATE <= #{tradeDate,jdbcType=DATE}
AND #{tradeDate,jdbcType=DATE} < = CREDIT_LINES.MDATE ) a

select (a.usedAmt+a.usedZizhuAmt+a.usedEnstustAmt)*100000000 usedAmtTotal from ( SELECT CREDIT_LINES.SEQNO SEQNO, CREDIT_LINES.PFLSH PFLSH, CREDIT_LINES.CUSTOMER_ID customerId, CREDIT_ASSETPOOL.ASSETPOOL_NAME as customerName, CREDIT_LINES.VDATE VDATE, CREDIT_LINES.MDATE MDATE, nvl(CREDIT_LINES.CREDIT_AMT,0)/100000000 creditAmt, CASE WHEN NVL(table1.amountSum,0)<0 THEN 0 ELSE NVL(table1.amountSum,0) END AS usedAmt, CASE WHEN NVL(table2.amountSum,0)<0 THEN 0 ELSE NVL(table2.amountSum,0) END AS usedZizhuAmt, CASE WHEN NVL(table3.amountSum,0)<0 THEN 0 ELSE NVL(table3.amountSum,0) END AS usedEnstustAmt FROM CREDIT_LINES INNER JOIN CREDIT_ASSETPOOL ON CREDIT_LINES.CUSTOMER_ID=CREDIT_ASSETPOOL.SEQNO LEFT JOIN( SELECT CREDIT_USING_SERIES.AST_SERIES_ID, SUM(CREDIT_USING_SERIES.AMOUNT)/100000000 amountSum FROM CREDIT_USING_SERIES WHERE CREDIT_USING_SERIES.IS_BOTTOM='N' AND CREDIT_USING_SERIES.STATUS='01' AND CREDIT_USING_SERIES.CDATE<=#{tradeDate,jdbcType=DATE} GROUP BY CREDIT_USING_SERIES.AST_SERIES_ID ) table1 ON CREDIT_LINES.CUSTOMER_ID=table1.AST_SERIES_ID LEFT JOIN( SELECT CREDIT_USING_SERIES.AST_SERIES_ID, SUM(CREDIT_USING_SERIES.AMOUNT)/100000000 amountSum FROM CREDIT_USING_SERIES LEFT JOIN FIN_PRODUCT ON CREDIT_USING_SERIES.FINPROD_ID=FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE ON CREDIT_USING_SERIES.P_FINPROD_ID=FIN_PRODUCT_TYPE.FINPROD_ID WHERE CREDIT_USING_SERIES.IS_BOTTOM='Y' AND CREDIT_USING_SERIES.STATUS='01' AND CREDIT_USING_SERIES.CDATE=( SELECT MAX(CREDIT_USING_SERIES.CDATE) FROM CREDIT_USING_SERIES WHERE CREDIT_USING_SERIES.IS_BOTTOM='Y' AND CREDIT_USING_SERIES.CDATE<=#{tradeDate,jdbcType=DATE} ) AND FIN_PRODUCT_TYPE.TYPE_7='04' GROUP BY CREDIT_USING_SERIES.AST_SERIES_ID ) table2 ON CREDIT_LINES.CUSTOMER_ID=table2.AST_SERIES_ID LEFT JOIN( SELECT CREDIT_USING_SERIES.AST_SERIES_ID, SUM(CREDIT_USING_SERIES.AMOUNT)/100000000 amountSum FROM CREDIT_USING_SERIES LEFT JOIN FIN_PRODUCT ON CREDIT_USING_SERIES.FINPROD_ID=FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE ON CREDIT_USING_SERIES.P_FINPROD_ID=FIN_PRODUCT_TYPE.FINPROD_ID WHERE CREDIT_USING_SERIES.IS_BOTTOM='Y' AND CREDIT_USING_SERIES.STATUS='01' AND CREDIT_USING_SERIES.CDATE=( SELECT MAX(CREDIT_USING_SERIES.CDATE) FROM CREDIT_USING_SERIES WHERE CREDIT_USING_SERIES.IS_BOTTOM='Y' AND CREDIT_USING_SERIES.CDATE<=#{tradeDate,jdbcType=DATE} ) AND FIN_PRODUCT_TYPE.TYPE_7!='04' GROUP BY CREDIT_USING_SERIES.AST_SERIES_ID ) table3 ON CREDIT_LINES.CUSTOMER_ID=table3.AST_SERIES_ID left join CREDIT_ASSETPOOL_DETAIL tt on CREDIT_LINES.CUSTOMER_ID=tt.SEQNO
and tt.FINPROD_ID = #{finprodId}
AND CREDIT_LINES.VDATE <= #{tradeDate,jdbcType=DATE}
AND #{tradeDate,jdbcType=DATE} < = CREDIT_LINES.MDATE ) a
